from __future__ import absolute_import
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sbts_fsm3.pages.panels.view import ViewPanel
from taf.selenium.sbts_fsm3.pages.modals import RestoreFactoryDefaultsModal
from taf.selenium.sbts_fsm3.pages.navigatable_page import NavigatablePage


class CentralizedRaeManagementPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Configuration', 'Centralized RAE Management']

    def __init__(self, driver, download_checker):
        super(CentralizedRaeManagementPage, self).__init__(driver)
        self._view_panel = CentralizedRaeManagementPageViewPanel(driver, download_checker)

    def get_beam_widths(self, rae_unit, frequency, timeout):
        return self._view_panel.get_beam_widths(rae_unit, frequency, timeout)

    def get_angles(self, rae_unit, vertical, horizontal, timeout):
        return self._view_panel.get_angles(rae_unit, vertical, horizontal, timeout)

    def get_weight_factors(self, rae_unit, downtilt, azimuth, timeout):
        return self._view_panel.get_weight_factors(rae_unit, downtilt, azimuth, timeout)

    def update_weight_factor_file(self, file_path, timeout):
        return self._view_panel.update_weight_factor_file(file_path, timeout)

    def save_weight_factor_file(self, rae_unit, file_name, timeout):
        return self._view_panel.save_weight_factor_file(rae_unit, file_name, timeout)

    def restore_factory_defaults(self, timeout):
        return self._view_panel.restore_factory_defaults(timeout)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class CentralizedRaeManagementPageViewPanel(ViewPanel):
    RAE_UNIT_XPATH = '//div[@class="rae-table"]//td[text()="{}"]'
    FREQUENCY_DROPDOWN_BUTTON = '//*[@*="$ctrl.frequency"]//button'
    DROP_DOWN_OPTION = '//wf-dropdown-item//li//span[text()="{}"]'
    GET_BEAM_WIDTHS_BUTTON = '//button[contains(text(), "Get Beamwidths")]'
    EXPECTED_RAE_MANAGE_PROGRESS = '//rae-management-progress//*[contains(text(), "{}")]'
    CURRENT_RAE_MANAGE_PROGRESS = '//rae-management-progress//*[@class="rae-progress-root"]/div//span'
    BEAM_WIDTH_DATA_DOWNLOAD = 'Beamwidth data downloaded'

    VERTICAL_DROPDOWN_XPATH = '//*[@*="$ctrl.vertical"]//button'
    HORIZONTAL_DROPDOWN_XPATH = '//*[@*="$ctrl.horizontal"]//button'
    GET_ANGLES_BUTTON = '//button[contains(text(), "Get Angles")]'
    ANGEL_DATA_DOANLOAD = 'Angle data downloaded'

    DOWNTILT_DROPDOWN_XPATH = '//*[@*="$ctrl.downtilt"]//button'
    AZIMUTH_DROPDOWN_XPATH = '//*[@*="$ctrl.azimuth"]//button'
    GET_WEIGHT_FACTORS_BUTTON = '//button[contains(text(), "Get Weight Factors")]'
    WEIGHT_FACTOR_DATA_DOWNLOADED = 'Weight factor data downloaded'
    WEIGHT_FACTOR_TD_ELEMENT = '//div[@class="rae-weight-factors-table"]//tbody//tree-table-td//span'
    WEIGHT_FACTOR_KEYS = ['Port', 'Polarity', 'Amplitude', 'Phase']

    INPUT_BUTTON_BY_CSS = "div[class='rae-button-group'] input"
    INPUT_BUTTON_BY_XPATH = '//div[@class="rae-button-group"]//input'
    WEIGHT_FILE_UPDATED_STATUS = 'Weight factor file updated'

    SAVE_BUTTON = '//button[contains(text(), "Save")]'
    WEIGHT_FILE_XPATH = '//td[contains(text(), "{}")]'
    FILE_SAVE = 'File saved from RAE'

    RESTORE_FACTORY_DEFAULTS_BUTTON = '//button[contains(text(), "Restore Factory Defaults")]'
    FACTORY_RESET_COMPLETED = 'Factory reset completed'

    def __init__(self, driver, download_checker):
        super(CentralizedRaeManagementPageViewPanel, self).__init__(driver, download_checker)

    def _click_rae_unit(self, rae_unit):
        self.click_enabled_element_after_visible((By.XPATH, self.RAE_UNIT_XPATH.format(rae_unit)))

    def get_beam_widths(self, rae_unit, frequency, timeout):
        self._click_rae_unit(rae_unit)
        self.select_element_from_dropdown_list_by_text_and_click(
            frequency,
            (By.XPATH, self.FREQUENCY_DROPDOWN_BUTTON),
            (By.XPATH, self.DROP_DOWN_OPTION.format(frequency))
        )
        self.click_enabled_element((By.XPATH, self.GET_BEAM_WIDTHS_BUTTON))
        try:
            self._wait_for_element_by((By.XPATH,
                                       self.EXPECTED_RAE_MANAGE_PROGRESS.format(self.BEAM_WIDTH_DATA_DOWNLOAD)),
                                      timeout)
            return self.BEAM_WIDTH_DATA_DOWNLOAD
        except TimeoutException:
            return self.get_text_by_xpath(self.CURRENT_RAE_MANAGE_PROGRESS)

    def get_angles(self, rae_unit, vertical, horizontal, timeout):
        self._click_rae_unit(rae_unit)
        self.select_element_from_dropdown_list_by_text_and_click(
            vertical,
            (By.XPATH, self.VERTICAL_DROPDOWN_XPATH),
            (By.XPATH, self.DROP_DOWN_OPTION.format(vertical))
        )
        self.select_element_from_dropdown_list_by_text_and_click(
            horizontal,
            (By.XPATH, self.HORIZONTAL_DROPDOWN_XPATH),
            (By.XPATH, self.DROP_DOWN_OPTION.format(horizontal))
        )
        self.click_enabled_element((By.XPATH, self.GET_ANGLES_BUTTON))
        try:
            self._wait_for_element_by((By.XPATH,
                                       self.EXPECTED_RAE_MANAGE_PROGRESS.format(self.ANGEL_DATA_DOANLOAD)), timeout)
            return self.ANGEL_DATA_DOANLOAD
        except TimeoutException:
            return self.get_text_by_xpath(self.CURRENT_RAE_MANAGE_PROGRESS)

    def _click_get_weight_factor_button(self, rae_unit, downtilt, azimuth, timeout):
        self._click_rae_unit(rae_unit)
        self.select_element_from_dropdown_list_by_text_and_click(
            downtilt,
            (By.XPATH, self.DOWNTILT_DROPDOWN_XPATH),
            (By.XPATH, self.DROP_DOWN_OPTION.format(downtilt))
        )
        self.select_element_from_dropdown_list_by_text_and_click(
            azimuth,
            (By.XPATH, self.AZIMUTH_DROPDOWN_XPATH),
            (By.XPATH, self.DROP_DOWN_OPTION.format(azimuth))
        )
        self.click_enabled_element((By.XPATH, self.GET_WEIGHT_FACTORS_BUTTON), timeout)

    def _get_weight_factor(self, timeout):
        weight_factor = {}
        try:
            self._wait_for_element_by((By.XPATH,
                                       self.EXPECTED_RAE_MANAGE_PROGRESS.format(self.WEIGHT_FACTOR_DATA_DOWNLOADED)),
                                      timeout)
            progress = self.WEIGHT_FACTOR_DATA_DOWNLOADED
        except TimeoutException:
            progress = self.driver.find_element_by_xpath(self.CURRENT_RAE_MANAGE_PROGRESS).text
            if "Data read from cache" not in progress:
                return [progress, []]

        value_list = []
        for index, elem in enumerate(self.driver.find_elements_by_xpath(self.WEIGHT_FACTOR_TD_ELEMENT)):
            value = elem.text
            if 'group' in value:
                group_name = value
                weight_factor.update({group_name: []})
            else:
                value_list.append(value)
                if index % 4 == 0:
                    weight_factor[group_name].append(dict(zip(self.WEIGHT_FACTOR_KEYS, value_list)))
                    value_list = []
        return [progress, weight_factor]

    def get_weight_factors(self, rae_unit, downtilt, azimuth, timeout):
        self._click_get_weight_factor_button(rae_unit, downtilt, azimuth, timeout)
        return self._get_weight_factor(timeout)

    def update_weight_factor_file(self, file_path, timeout):
        self.display_element(self.INPUT_BUTTON_BY_CSS)
        elem = self.driver.find_element_by_xpath(self.INPUT_BUTTON_BY_XPATH)
        elem.send_keys(file_path)
        self._wait_for_element_by((By.XPATH,
                                   self.EXPECTED_RAE_MANAGE_PROGRESS.format(self.WEIGHT_FILE_UPDATED_STATUS)), timeout)
        self.hide_element(self.INPUT_BUTTON_BY_CSS)
        return self.WEIGHT_FILE_UPDATED_STATUS

    def save_weight_factor_file(self, rae_unit, file_name, timeout):
        self._click_rae_unit(rae_unit)
        self.click_enabled_element((By.XPATH, self.WEIGHT_FILE_XPATH.format(file_name)))
        self.click_and_wait_for_corresponding_element_visible(self.SAVE_BUTTON,
                                                              self.EXPECTED_RAE_MANAGE_PROGRESS.format(self.FILE_SAVE),
                                                              timeout=timeout)
        return [self.FILE_SAVE, ''.join([self.download_dir, '/', file_name])]

    def restore_factory_defaults(self, timeout):
        self.click_enabled_element((By.XPATH, self.RESTORE_FACTORY_DEFAULTS_BUTTON))
        modal = RestoreFactoryDefaultsModal(self.driver)
        modal.wait_until_restore_factory_defaults_modal_appear(timeout)
        modal.restore()
        self._wait_for_element_by((By.XPATH,
                                   self.EXPECTED_RAE_MANAGE_PROGRESS.format(self.FACTORY_RESET_COMPLETED)), timeout)
        return self.FACTORY_RESET_COMPLETED
